import{_ as t,o,c as a,a3 as s}from"./chunks/framework.CpLciM8b.js";const u=JSON.parse('{"title":"Usage and limits","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage-and-limits.md","filePath":"guide/usage-and-limits.md","lastUpdated":1790776277000}'),r={name:"guide/usage-and-limits.md"};function i(n,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="usage-and-limits" tabindex="-1">Usage and limits <a class="header-anchor" href="#usage-and-limits" aria-label="Permalink to &quot;Usage and limits&quot;">​</a></h1><p>Flakemetry costs money in two places: model tokens for root-cause analysis, and storage. Both can be seen and capped per project.</p><h2 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h2><ul><li><strong>Usage</strong> (<code>/usage</code>, linked from the project list as <em>usage and limits</em>) is the operator&#39;s view. It shows every project in the workspaces you own or administer, with today&#39;s AI tokens, stored executions, rollup rows and artifact storage, each against its cap. A figure over its cap is shown in red.</li><li><strong>Settings → Data</strong> shows the same figures for one project, along with its retention windows and the export.</li></ul><h2 id="how-storage-is-tiered" tabindex="-1">How storage is tiered <a class="header-anchor" href="#how-storage-is-tiered" aria-label="Permalink to &quot;How storage is tiered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>What it holds</th><th>Kept</th></tr></thead><tbody><tr><td>Raw executions (hot)</td><td>One row per test execution: status, duration, error, spans</td><td>For the retention window, and within the execution cap</td></tr><tr><td>Daily rollups (cold)</td><td>One row per test, per suite and per project per day</td><td>Kept when raw executions are pruned, so trends and history survive</td></tr><tr><td>Artifacts</td><td>Screenshots, videos and traces in object storage</td><td>For the artifact retention window, and within the artifact cap</td></tr></tbody></table><p>Trends, suite health and the cost-of-flakiness panel read the rollups, so trimming raw executions does not erase a project&#39;s history. Flaky scores are recomputed from the raw executions that remain, so a very low execution cap also shortens the history a score rests on. Keep the cap well above what one run times the policy&#39;s minimum samples produces.</p><h2 id="caps" tabindex="-1">Caps <a class="header-anchor" href="#caps" aria-label="Permalink to &quot;Caps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Policy field</th><th>Environment variable</th><th>Effect</th></tr></thead><tbody><tr><td>Daily LLM token budget</td><td><code>FLAKEMETRY_AI_DAILY_TOKEN_BUDGET</code></td><td>Root-cause analysis pauses for the rest of the UTC day once it is spent. <code>0</code> turns analysis off. The <code>ai_budget_spent</code> notification says so when it happens</td></tr><tr><td>Most executions to keep</td><td><code>FLAKEMETRY_STORAGE_MAX_EXECUTIONS</code></td><td>The worker deletes the oldest raw executions beyond the cap. <code>0</code> means no cap</td></tr><tr><td>Most artifact storage (MB)</td><td><code>FLAKEMETRY_STORAGE_MAX_ARTIFACT_MB</code></td><td>The worker deletes the oldest artifacts beyond the cap. <code>0</code> means no cap</td></tr></tbody></table><p>Set a cap per project under <strong>Settings → Policy</strong>, or for every project with the environment variable. The environment wins, and the Policy page shows which source is in effect. Storage caps are enforced by the worker&#39;s retention sweep, which runs when the worker starts and every six hours after that. They sit alongside the retention windows (<code>FLAKEMETRY_EXECUTION_RETENTION_DAYS</code> and friends): data goes when it is older than the window <strong>or</strong> beyond the cap, whichever comes first.</p>',10)])])}const w=t(r,[["render",i]]);export{u as __pageData,w as default};
